{
    std::md5 hash;
    hash.update(std::md5::string_type(msg.begin(), msg.end()));
    hash.finalize();
    md5_digest = hash.digest();
}

constexpr float BASE_MULTIPLIER = 16777619.0f;  // Knuth's multiplicative hash constant
float hash_sum = 0.0f;
for (unsigned char byte : md5_digest) {
    hash_sum = std::fmaf(BASE_MULTIPLIER, hash_sum, static_cast<float>(byte));
}

return std::fmodf(std::abs(hash_sum), 1.0f);
